import { db } from '../db';

export async function getUserDashboard(userId: string) {
  const user = await db.user.findUnique({
    where: { id: userId },
  });

  const followers = await db.follow.findMany({
    where: { followingId: userId },
  });

  // Get profile info for each follower to show in the dashboard
  const followerProfiles = [];
  for (const follow of followers) {
    const profile = await db.user.findUnique({
      where: { id: follow.followerId },
      select: { id: true, name: true, avatar: true, bio: true },
    });
    followerProfiles.push(profile);
  }

  const recentPosts = await db.post.findMany({
    where: { authorId: userId },
    orderBy: { createdAt: 'desc' },
    take: 10,
  });

  return {
    user,
    followers: followerProfiles,
    recentPosts,
  };
}

import { resizeImage } from '../processors/resize';
import { generateThumbnails } from '../processors/thumbnails';
import { runModeration } from '../processors/moderation';
import { saveToS3 } from '../storage/s3';

export async function handleUpload(file: Buffer, userId: string) {
  // TODO: This all needs to move to background jobs
  const resized = await resizeImage(file, [1080, 720, 480, 240, 120]);
  const thumbnails = await generateThumbnails(resized);
  await runModeration(file); // Can take 2-3 seconds, external API call
  const urls = await saveToS3(resized, thumbnails, userId);

  return { urls };
}
